// ESP32 Mini-Roboter: Servo + Ultraschall + LED
#include <ESP32Servo.h>

// --- Pin-Definitionen ---
#define SERVO_PIN  13
#define TRIG_PIN   5
#define ECHO_PIN   18
#define LED_PIN    12

Servo radarServo;

// --- Abstand messen ---
float measureDistance() {
  digitalWrite(TRIG_PIN, LOW);
  delayMicroseconds(2);
  digitalWrite(TRIG_PIN, HIGH);
  delayMicroseconds(10);
  digitalWrite(TRIG_PIN, LOW);
  long duration = pulseIn(ECHO_PIN, HIGH, 25000); // Timeout 25 ms
  if (duration == 0) return 999.0; // kein Echo → sehr weit
  return duration * 0.0343 / 2.0;
}

// --- LED blinken ---
void blinkLED(int delayMs) {
  digitalWrite(LED_PIN, HIGH);
  delay(delayMs);
  digitalWrite(LED_PIN, LOW);
  delay(delayMs);
}

void setup() {
  Serial.begin(115200);
  radarServo.attach(SERVO_PIN);
  pinMode(TRIG_PIN, OUTPUT);
  pinMode(ECHO_PIN, INPUT);
  pinMode(LED_PIN, OUTPUT);
}

void loop() {
  float minDist = 999.0;
  int   minAngle = 0;

  // --- Sweep 0° → 180° ---
  for (int angle = 0; angle <= 180; angle += 10) {
    radarServo.write(angle);
    delay(50);
    float d = measureDistance();
    Serial.print("Winkel: ");
    Serial.print(angle);
    Serial.print("°  Abstand: ");
    Serial.print(d);
    Serial.println(" cm");
    if (d < minDist) {
      minDist  = d;
      minAngle = angle;
    }
  }

  Serial.print(">>> Nächstes Hindernis: ");
  Serial.print(minDist);
  Serial.print(" cm bei ");
  Serial.print(minAngle);
  Serial.println("°");

  // Entfernung (5..100 cm) → Blink-Tempo (50..500 ms)
  int blinkDelay = (int)map((long)minDist, 5, 100, 50, 500);
  blinkDelay = constrain(blinkDelay, 50, 500);
  blinkLED(blinkDelay);
}
